    private void PickColor(object sender,MouseButtonEventArgs e){if(_snapshot==null)return;var p=e.GetPosition(_before);double scale=Math.Min(_before.ActualWidth/_snapshot.PixelWidth,_before.ActualHeight/_snapshot.PixelHeight);if(scale<=0)return;double x=(p.X-(_before.ActualWidth-_snapshot.PixelWidth*scale)/2)/scale,y=(p.Y-(_before.ActualHeight-_snapshot.PixelHeight*scale)/2)/scale;if(x<0||y<0||x>=_snapshot.PixelWidth||y>=_snapshot.PixelHeight)return;var b=ImageTransfer.Bgra(new CroppedBitmap(_snapshot,new((int)x,(int)y,1,1)));string hex=$"#{b[2]:X2}{b[1]:X2}{b[0]:X2}";new[]{_background,_fill,_foreground,_stroke}[Math.Max(0,_pickTarget.SelectedIndex)].Text=hex;}
